INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(352500, 0, 3525, 0, 0, 0, 'Bloodmyst Isle', 'Bloodmyst Isle is the northern of the two isles off the coast of Kalimdor, a land of forested hills and mountains that the draenei first named Silvergale for its beauty. Long ago it belonged to the night elves of Loreth''Aran, whose riders flew green dragons until the black dragonflight destroyed their city and the Sundering broke the land apart; their ruins still crumble along the eastern shore. When the Exodar fell, shards of its crystals rained across the island and one of its great power cores buried itself in the western mountains. Fluid leaking from it has turned the waters red, and the corruption spreads through trees, bears, moths and water spirits alike, many of them now riddled with crystal. Worse, the blood elves the draenei fought aboard the ship survived the crash. Calling themselves the Sunhawks, they hold the west around the Vector Coil. Nazzivus satyrs, Wrathscale naga and maddened owlkin add to the danger. Against them all stands Blood Watch, the Hand of Argus outpost at the island''s heart.', 'warcraft.wiki.gg/wiki/Bloodmyst_Isle (Silvergale, Loreth''Aran, Dragon Wars, Sundering, crystal storm, Sunhawks); quest 9694 description (called it Silvergale, blood elves survived the crash); quest 9748 reward (water turned red by core fluid); quest 9641 description (shards inside bears, ravagers, flutterers, treants); quest 10067 description (water spirits turning to crystal); quest 9759 description (power core jutting from the mountain)'),
(352501, 1, 3525, 1, 0, 0, 'Kessel''s Crossing', 'Kessel''s Crossing is a draenei camp on the southern edge of Bloodmyst, where the road north from Azuremyst first reaches the isle. It belongs to Kessel, lord of the elekk, and the great beasts graze here under the eye of Vorkhan the herder. The Exodar carried ravagers from Outland as specimens, and Vorkhan fears the survivors, now loose near the coast, will push out the island''s own predators. Nearby, Aonar bakes pies from the sand pears of the island''s healthier south, sharing them with the elekk, who would steal them anyway. He warns newcomers that when Kessel offered him work caring for the elekk, the job came with a shovel.', 'quest 9625 description (road north to Kessel''s Crossing); quest 9634 description and request text (ravager specimens, displacing native predators); quest 9624 description (sand pears on the uncorrupted part, elekk steal fruit); npc_text 9037 (Aonar on Kessel and the shovel); npc_text 9041 (Kessel, lord of the elekk); zone_areas: Vorkhan 17586, Aonar 17599, Kessel 17649, Elekk 17530 in area 3602'),
(352502, 1, 3525, 2, 0, 0, 'The Lost Fold', 'South of Blood Watch, across a bridge, the hollow of the Lost Fold holds wreckage the Exodar shed as it fell, and ravagers have made the debris their nest. Their hatchlings swarm here and along the nearby Beryl Coast, the spreading brood of the Outland specimens that survived the crash. For all that, this is one of the less corrupted corners of Bloodmyst. Harbinger Mikolaas had the first of his crystal samples cut from a crystal at this impact site, to serve as a baseline against which the island''s more tainted shards could be measured.', 'quest 9581 description and reward (ravager infested debris south of town across the bridge, less corrupted region, baseline); gameobject 181779 Impact Site Crystal stands in area 3909 (posarea); zone_areas: Bloodmyst Hatchling 17525 in 3909 and 3583; quest 9634 description (ravager specimens)'),
(352503, 1, 3525, 3, 0, 0, 'Bristlelimb Enclave', 'The Bristlelimb furbolgs, sworn enemies of the Stillpine of Azuremyst, keep a cluster of camps in the southeast of Bloodmyst. Here they hold Princess Stillpine, daughter of the Stillpine high chief, in a cage, and mean to sacrifice her to their gods. Only High Chief Bristlelimb carries the key, and he shows himself only once enough of his warriors and shaman have fallen, roaring for vengeance. Freed, the princess thanks her rescuer and hurries away to bring the news to her father, and the Stillpine ambassador at Blood Watch offers relics to the stranger their prophecy had already named as their hero. Other Stillpine have been less fortunate in this place.', 'quest 9667 description, objectives and reward; creature_text 17702 (Face the wrath of Bristlelimb), 17682; zone_areas: Princess Stillpine 17682, cage 181928, High Chief Bristlelimb 17702, Young Furbolg Shaman 17542 in 3600; azuremyst.json (Bristlelimb and Stillpine at war); smart_scripts 17682 (waypoint then despawn), creature_text 17682'),
(352504, 1, 3525, 4, 0, 0, 'Wrathscale Lair', 'Northeast of Kessel''s Crossing, on the eastern coast, the Wrathscale naga keep a lair ruled by Lord Xiz. They grew bold enough to creep up on the draenei camp at the crossing under cover of darkness, and Kessel answered in kind: Lord Xiz was slain in his own lair and a draenei banner driven through his body, so that the naga would know fear whenever they saw that standard. Screamers and shorestalkers guard the lair, and Wrathscale marauders and sorceresses range north along the waters of the Crimson Reach toward the ruins of Loreth''Aran.', 'quest 9666 description and reward; zone_areas: Lord Xiz 17701 and Wrathscale Shorestalker/Screamer in 3590; Wrathscale Marauder/Sorceress in 3589 and 3591; DB spawn averages (Wrathscale Lair on the east coast, marauders toward Loreth''Aran)'),
(352505, 1, 3525, 5, 0, 0, 'Blood Watch', 'Blood Watch is the forward base of the Hand of Argus on Bloodmyst, one of two the order runs on the isles. Exarch Admetius leads it with the three vindicators of the Triumvirate, while Harbinger Mikolaas sees to its defenses. The inn is a salvaged pod that Caregiver Topher Loaal is still furnishing with supplies sent from the Exodar, and a copy of Trans-dimensional Ship Repair for Simpletons lies open at a chapter on Vector Coil breaches. A captured Sunhawk agent sits in a makeshift prison. The Stillpine keep an ambassador here, and Anchorite Paetheus, a collector of knowledge from many peoples, has written to the night elves of Auberdine proposing an alliance.', 'quest 9694 description (one of two forward bases); npc_text 9022 (Admetius, leader of Blood Watch); quest 9603 description, 9604 reward (salvaged pod inn, supplies from Nurguni); page_text 2925 (ship repair book open at Vector Coil Breaches); zone_areas: Captured Sunhawk Agent 17824, Makeshift Prison 182012, Frasaboo 18803 in 3584; npc_text 9029 (Paetheus'' collection); quest 9632 description (letter to Auberdine); quests 9605, 9606; creature_queststarter 9632 (Anchorite Paetheus 17424)'),
(352506, 1, 3525, 6, 0, 0, 'Ruins of Loreth''Aran', 'On the eastern side of Bloodmyst stand the remnants of Loreth''Aran, a night elf city destroyed in the Dragon Wars and broken apart by the Sundering, its other stones scattered across nearby islands. A pavilion of broken columns sits west of a partly submerged tower, and among these ruins an ancient journal and a buried box long lay hidden. The Wrathscale naga hold the place now. When Harbinger Mikolaas sent a team of draenei cartographers to map it, they never returned: they were found dead among their ransacked packs, pierced by naga weapons, and the crystal holding their survey had been carried off.', 'warcraft.wiki.gg/wiki/Ruins_of_Loreth''Aran; quest 9550 description (pavilion west of a partially submerged tower, eastern coast); quest 9620 description and reward, 9628 description; zone_areas: Battered Ancient Book 181756, Mound of Dirt 181758, Draenei Cartographer 17600, Wrathscale in 3591'),
(352507, 1, 3525, 7, 0, 0, 'The Bloodcursed Reef', 'Off the northeast coast lies the Bloodcursed Reef, a spoiled and desecrated stretch of sea where the bloodcurse has sunk ship after ship, among them the Lost Hope of Captain Edward Hanes. Those it took do not rest. The ghosts of drowned voyagers drift along its deeper ledges, and bloodcursed naga patrol above them. South of the reef rises Bloodcurse Isle, where the naga keep a shrine around a statue of their beloved queen, Azshara. Their leader, Atoph the Bloodcursed, rises in fury against anyone who dares defile it.', 'quest 9672 reward text (bloodcurse sank all these ships, spoiled desecrated water); quest 9682 description (voyagers on a deeper ledge, ghosts); quest 9683 description; creature_text 17715 (Who dares defile the statue of our beloved?); warcraft.wiki.gg/wiki/Bloodmyst_Isle (Lost Hope sunk on the reef); zone_areas: Bloodcursed Naga 17713, Bloodcursed Voyager 17714 in 3604; Statue of Queen Azshara 181964 in 3612'),
(352508, 1, 3525, 8, 0, 0, 'Wyrmscar Island', 'Wyrmscar Island, off the northeast tip of Bloodmyst, was once part of Loreth''Aran, where night elf riders flew green dragons given by Ysera. The black dragonflight fell on the city as it slept, and the bones of the green dragons who rose to defend it still lie across the island. Their spirits linger as restless whelps and broodlings, unable to pass into the Dream, and the ghost of Prince Toreth keeps watch among them. At Talon Stand on the island''s peak burns an ever-burning pyre, and overhead circles the spectral black dragon Razormaw. A rare mushroom called Ysera''s tear grows here, and the ghost of a human captain haunts the shore.', 'warcraft.wiki.gg/wiki/Wyrmscar_Island; npc_text 9058, 9059 (Toreth on Ysera and the attack); quest 9688 description (whelps are spirits bound to the land); quest 9689 description (pyre at the top of the mountain, Razormaw circling); quest 9649 description (Ysera''s tear); zone_areas: Ever-burning Pyre 181988 in 3599; Veridian whelps and Ysera''s Tear in 3598 and 3907; Captain Edward Hanes 17712 in 3598'),
(352509, 1, 3525, 9, 0, 0, 'Ragefeather Ridge', 'Ragefeather Ridge rises north of Blood Watch, across the Crimson Reach from Wyrmscar Island. Its owlkin lived in harmony with the land for thousands of years, but the flock is tranquil no longer: its birds are now infected, contaminated and irradiated, and they have taken to visiting the shores of Wyrmscar to carry off the bones of fallen green dragons, gathering them in their own encampments for some ritual. Prince Toreth calls it sacrilege, for the theft has stirred the restless spirits of Ysera''s brood, and he can only wonder what has caused the owlkin such distress.', 'quest 9687 description and reward (to the west across the Crimson Reach; tranquil owlkin stealing bones; a ritual; harmony for thousands of years); zone_areas: Infected, Contaminated and Irradiated Wildkin and Dragon Bone 181981 in 3601'),
(352510, 1, 3525, 10, 0, 0, 'The Bloodwash', 'The Bloodwash is a stretch of the northern shore claimed by the Blacksilt murlocs, whose seers, warriors and shorestrikers work its shallows. Hidden inside an old turtle shell on the beach, the gnome Clopper Wizbang watches them in secret, convinced that a single glimpse of him would spoil his data. Just offshore, beneath the waves, lies the Hidden Reef, where more Blacksilt murlocs prowl and watery aspects drift around Aqueous, a powerful elemental of water.', 'npc_text 9054 (Clopper in a turtle shell); quest 10063 description (turtle shell on the northern shore); quest 9548 description; zone_areas: Blacksilt Seer/Warrior/Shorestriker and Clopper 17421 in 3906; Aqueous 17275, Watery Aspect, Blacksilt in 3596; exodar.json Call of Water (hidden reef off the northern shore, imbalance)'),
(352511, 1, 3525, 11, 0, 0, 'Nazzivian', 'Southwest of Blood Watch lies Nazzivian, the stronghold of the Nazzivus satyrs. At its heart stands a grotesque monument whose glyphs speak of the satyrs'' origins: the Nazzivus descend from the first twisted soul to bargain with the Burning Legion, and they feed on the corruption the Exodar''s crash has spread. Rogues, felsworn and summoners haunt the camp among warped treants and bears, and fel cone fungus sprouts from the soil. The satyrs have summoned a felguard named Tzerak into their midst, and his armor, black metal that seems to drink the light, told the draenei that the satyrs are renewing their bond with the Legion.', 'quest 9567 description (grotesque monument, feeding on corruption, southwest); quest 9568 description (descendants of the first twisted creature); quest 9594 description and reward (deep black metal absorbing light, felguard, renewing contacts); warcraft.wiki.gg/wiki/Nazzivian (monument glyphs, Tzerak summoned); creature_text 17528; zone_areas: Nazzivus Satyr/Rogue/Felsworn/Summoner, Tzerak 17528, Fel Cone Fungus, Corrupted Treant in 3592'),
(352512, 1, 3525, 12, 0, 0, 'Axxarien', 'North of Blood Watch, Axxarien is the seat of Zevrax, leader of the island''s satyrs. His hellcallers, tricksters and shadowstalkers guard the corrupted crystals the satyrs have been gathering, and the draenei fear the creatures will turn the Exodar''s power against its owners. Vindicator Aalesia of Blood Watch wanted Zevrax slain and the crystals recovered before the threat could grow. Harbinger Mikolaas sent for a shard of the Axxarien crystal itself, the last and least predictable of the samples he boxed up for study at the Exodar.', 'quest 9569 description and reward (go north to their leader in Axxarien, corrupted crystals); quest 9568 description (use the crystals'' power against us); quest 9585 description and reward; zone_areas: Axxarien Shadowstalker/Trickster/Hellcaller, Zevrax 17494, Corrupted Crystal 181770/181771 in 3593'),
(352513, 1, 3525, 13, 0, 0, 'Bladewood', 'Bladewood lies northwest of Blood Watch, and Sunhawk spies swarm through it in such numbers that Vindicator Boros half suspects they are multiplying. It was the first ground the Hand of Argus sent its recruits to clear. The blood elves are at work on the fallen crystals here, altering them and harvesting them for some magical apparatus. A shard cut from one of the altered crystals pulses as it catches the light, unlike the cleaner crystal of the south, and Harbinger Mikolaas found the change worrying enough to note it in his report to the Exodar.', 'quest 9694 description and request text; quest 9584 description and reward; zone_areas: Sunhawk Spy 17604 x18 in 3585; Altered Bloodmyst Crystal 181780 in 3585 (posarea)'),
(352514, 1, 3525, 14, 0, 0, 'The Cryo-Core', 'West of Blood Watch lies the Cryo-Core, a section of the Exodar that held stasis pods like those the survivors of Ammen Vale crawled out of, along with stores of medical supplies. When the draenei learned of it, they hoped to find more of their people alive. They found blood elves instead. Sunhawk reclaimers strip the wreckage of anything of value, and the dead lie where they fell, among them the technician Galaen, whose amulet was torn from him by looters and whose journal recorded the torment of a captured vindicator.', 'quest 9703 description and reward (pod holding area, medical supplies, just blood elves, no survivors); quest 9578 description, 9579 description; page_text 2937 (Galaen''s journal); zone_areas: Sunhawk Reclaimer, Medical Supplies, Galaen''s Corpse 17508, Galaen''s Journal 182032 in 3588'),
(352515, 1, 3525, 15, 0, 0, 'Amberweb Pass', 'Amberweb Pass, in the western wilds, belongs to spiders grown huge and savage from the crystal contamination. An expedition from Blood Watch was ambushed here. The brood''s matriarch, Zarakh, fell upon the party with terrible speed, wrapped its members in cocoons and laid her eggs beside them, meaning them as food for her young. Researcher Cornelius cut himself free but refused to leave without his men, while Achelus, the outpost''s expeditionary officer, escaped to Blood Watch and found no one there willing to go back. In the end, more than half the team was cut free alive.', 'quest 9669 description and reward; quest 9670 description and reward; npc_text 9042, 9045; zone_areas: Myst Spinner/Leecher, Webbed Creature, Zarakh 17683, Researcher Cornelius 17686 in 3597'),
(352516, 1, 3525, 16, 0, 0, 'Vindicator''s Rest', 'Vindicator''s Rest is a small Hand of Argus outpost on consecrated ground northwest of Blood Watch, set up to keep watch on the Sunhawks around the Vector Coil. It is badly outnumbered. Its scouts found the blood elves'' portal at a heavy cost, and Scout Jorli, gravely wounded, waits for a safe road home through the enraged ravagers that prowl beyond the hallowed ground. Mutated tanglers near the Coil have learned to set and hide traps, and Vindicator Corin holds the post patiently, waiting for a champion. Beside her waits Demolitionist Legoso, ready to carry his explosives up the mountain.', 'quest 10064 description (forward base, outnumbered, watch on Vector Coil); quest 10065 description (wounded, consecrated ground, ravagers); quest 9741 description; npc_text 9591 (buried too many friends); quest 10066 description (tanglers set traps); quest 9761 description and request text; zone_areas: Corin 17986, Legoso 17982, Scouts 17926/17927 in 3608'),
(352517, 1, 3525, 17, 0, 0, 'The Foul Pool', 'North of Vindicator''s Rest lies the Foul Pool, waters poisoned almost beyond recognition. Most creatures touched by the crystals bear strange marks and small shards in their flesh, but the fouled water spirits that dwell here are changing in a way the draenei have never seen: they are turning entirely to crystal. The Hand wants them gone before the Sunhawks learn to use them as a new source of energy. The pool''s filth has a nearer source as well. Not far off lies the camp of a blood elf researcher, Tel''athion the Impure, whose barrels fed his work into the island''s water.', 'quest 10067 description and reward; zone_areas: Fouled Water Spirit 17358 x28 in 3595; Barrel of Filth 181699 in 3603; warcraft.wiki.gg/wiki/Bloodmyst_Isle (Tel''athion, blood elf researcher contaminating the water); exodar.json Call of Water (Tel''athion''s camp, not retold); creature_template 17359 Tel''athion the Impure (not used as a trigger)'),
(352518, 1, 3525, 18, 0, 0, 'The Vector Coil', 'The Vector Coil is a colossal power core of the Exodar that lodged in the mountains of western Bloodmyst when the ship came down, a great red crystal still jutting from the slope. Fluid leaking from it has stained the island''s waters red. The Sunhawks made it their stronghold, and their agents and saboteurs swarm its paths, while at its summit their leader, Sironas, siphons its energy for herself. Far to the northeast, north of Blood Watch, lies the Warp Piston, where the blood elves opened their sun portal to Outland more than once, and where void anomalies still spill from the rifts it left.', 'quest 9759 description (power core jutting out of the mountainside); creature_text 17982 (red crystal, siphoning energy); quest 9748 reward; warcraft.wiki.gg/wiki/Vector_Coil; quest 9700 description and reward (sun portal site near the Warp Piston, void anomalies); zone_areas: Sunhawk Agent/Saboteur, Sironas 17678, Matis 17664 in 3586; Void Anomaly in 3587'),
(352519, 2, 3525, 1, 1, 0, 'Exarch Admetius', 'Exarch Admetius leads Blood Watch. He asks every recruit what Argus means to them, for many draenei barely remember the world where their people split from the man''ari, and he tastes the word eredar only to call it disgusting. He has no stomach for cruelty: when questioning a Sunhawk prisoner failed, he ruled torture out and cast a spell to make one of his own agents look and sound like a blood elf, so the truth could be coaxed out instead. His plan for the Vector Coil was simple, to blow it up, yet he refused to order any draenei on so deadly a mission. When it was done, he hailed the hero before all of Blood Watch.', 'npc_text 9022; quest 9693 description; quest 9756 description; quest 9753 reward (blow the thing up); quest 9761 description (exarch will not order any agent); creature_text 17658'),
(352520, 2, 3525, 2, 1, 0, 'The Triumvirate of the Hand', 'Three vindicators, the Triumvirate of the Hand, command the Hand of Argus from Blood Watch. Boros, the first, teaches that the Hand serves and dies without question, then laughs at his own fervor; he has also learned to purify the crystal shards cut from the island''s beasts into useful gems. Kuros, the second, took his seat only recently, succeeding his own master, Vindicator Saruan, after the search for him was abandoned, and he wept when he learned how Saruan had suffered. Aesom, the third, hunts the Sunhawks camp by camp, sworn to search out every hiding place until Sironas is found.', 'warcraft.wiki.gg/wiki/Hand_of_Argus (Triumvirate, Boros first, Saruan former second); npc_text 9044, 9077, 9117; quest 9693 reward (Boros laughs); quest 9641 description; quest 9706 reward; quest 9746 request text'),
(352521, 2, 3525, 3, 1, 0, 'Kessel', 'Kessel calls himself lord of the elekk and a disciple of the Hand of Argus, and recruits who would join the order are tested at his camp on the road into Bloodmyst. His tests are hard by design. He lends his own elekk for a desperate ride, with a warning to keep it out of water, and he does not flinch from bloodshed. Yet he takes no pleasure in it. Heavy-handed violence is not the draenei way, he says, but his people learned what reluctance costs when the orcs slaughtered them. To become one of the Hand is a rebirth, and with birth comes pain. Honorable people, he warns, cannot always act honorably.', 'npc_text 9041; quest 9663 description; quest 9666 reward; quest 9668 description; npc_text 9037 (old man Kessel)'),
(352522, 2, 3525, 4, 1, 0, 'Sironas', 'Sironas leads the Sunhawk blood elves on Bloodmyst, yet she is no elf but an eredar, one of the man''ari the draenei fled long ago. A captured Sunhawk, fooled by a draenei in disguise, let slip that she had lived among the draenei so long she could pass for one of them. Her aims were those of the Sun King: to enslave the naaru O''ros and take back the Exodar. She poisoned the land with fallout from the Vector Coil, held the captured vindicator Saruan for plans of her own, and claimed the power to turn eredar into savage man''ari. When the Coil was finally breached, she was found at its summit, drawing its power into herself.', 'quest 9759 description (Sironas the eredar); npc_text 9137-9141 (captured agent: served under Sironas on Outland, transformation claim, lived among the draenei); quest 9753 description; page_text 2937 (plans for Saruan); creature_text 17982 (siphoning energy), 17678; warcraft.wiki.gg/wiki/Sironas; gossip_menu_option 7531-7537 (disguised player''s lines); smart_scripts 17678, 17982'),
(352523, 2, 3525, 5, 1, 0, 'Matis the Cruel', 'Matis the Cruel, herald of Sironas, was the ruthless Sunhawk lieutenant who held Vindicator Saruan. Before the eyes of the captive technician Galaen, bound and weeping, the Sunhawks beat Saruan without mercy while Matis treated such cruelty as nothing out of the ordinary. When Saruan fell senseless, Matis splashed tainted water over him to wake him, then paced in fear of what Sironas would do to him if her prisoner died. Galaen''s journal named him. Kuros, Saruan''s pupil, wanted Matis brought back alive to face the Triumvirate''s justice, and draenei trackers wait for the flare that will mean he has been found. Once taken, he was to be tried at once.', 'creature_template 17664 (Herald of Sironas); page_text 2937; quest 9706 reward; quest 9711 description and reward; creature_text 17843 (Kuros orders trackers, Matis alive); creature_text 17664'),
(352524, 2, 3525, 6, 1, 0, 'Harbinger Mikolaas', 'Harbinger Mikolaas keeps the defenses of Blood Watch, and his first lesson for newcomers is vigilance: Bloodmyst claims the careless first, then slowly wears down even the most guarded. The leaders at the Exodar load him with other duties too, from mapping the island to gathering crystal samples for study, though it is hardly safe to send researchers out and he cannot spare the soldiers to guard them. He feels each loss. When his cartographers were found dead at Loreth''Aran, he clenched his fists and said too many good men had already fallen. He posts bounties on the beasts that prey on his people, such as the bear Deathclaw, and sends what help he can to the outnumbered Vindicator''s Rest.', 'npc_text 9033; quest 9581 description; quest 9620 description; quest 9628 reward; quest 9646 description; quest 10064 description'),
(352525, 2, 3525, 7, 1, 0, 'Morae', 'Morae, the herbalist of Blood Watch, says her days aboard the Exodar already feel a lifetime away, and that soon this island of mutant creatures and endless blood elf agents will be all she remembers. She has made its corruption her study, gathering crystallized bark from corrupted treants, marking Blacksilt murlocs on the southwestern coast with a harmless tagging device, and puzzling over a red crystal pendant worn by a murloc named Cruelfin, who she suspects grew strong on its power. Beneath the work lies a private search. Her husband Galaen, a technician of the Cryo-Core, wore a pendant matching her own, and she would rather hear of his death than never know.', 'npc_text 9034; quest 9574 description; quest 9629 description; quest 9576 reward; quest 9578 description'),
(352526, 2, 3525, 8, 1, 0, 'Prince Toreth', 'Ten thousand years ago Prince Toreth was a prince of Loreth''Aran, a dragon rider blessed by Ysera of the Dream. Now he is a ghost on Wyrmscar Island, and he greets the living with scorn: can they not see they stand on sundered earth? He calls himself a cruel reminder of a civilization long gone, anchored to a land he failed to protect. He was the last of his people to die, and with his final breath he swore a blood oath, his blood for this world, becoming the sole keeper of their history. He cannot rest until he knows the story of the dragon riders of Loreth''Aran will not be lost.', 'npc_text 9056, 9057, 9058, 9060 (Toreth gossip chain); creature_template 17674 (Dragon Riders of Loreth''Aran); warcraft.wiki.gg/wiki/Ruins_of_Loreth''Aran'),
(352527, 2, 3525, 9, 1, 0, 'Captain Edward Hanes', 'Edward Hanes was captain of the ship Lost Hope, and Admiral Odesyus knew him as a man who died of scurvy twenty years ago. Hanes scoffs at that. By his own account he died on the wild shores of Wyrmscar Island as food for the dragons, and his ghost has lingered there ever since, looking over a land that still bears the scars of its past and wondering whether they will ever heal. Death has not made him idle. He appeared one night in the admiral''s tent to plead for help, for the bloodcurse that sank so many ships still holds hundreds of souls captive in the nearby reef.', 'quest 9751 and 9672 descriptions (died of scurvy 20 years ago, appeared in the tent); quest 9672 reward (scurvy my foot, food for the dragons); npc_text 10352; quest 9683 reward (hundreds of souls)'),
(352528, 2, 3525, 10, 1, 0, 'Clopper Wizbang', 'Clopper Wizbang is, by his own account, the first gnome ever to join the Explorers'' League, and he has set up house inside a beached turtle shell on Bloodmyst''s northern shore to watch the Blacksilt murlocs unseen. When the murlocs carried off his equipment, he declared it a priceless observation in its own right. He collects their crude idols and knives for a museum in Ironforge, drafts grand reports for the gentlemen there, and offers his helpers credit as co-authors. The dwarf Prospector Nachlan, sent along on the expedition to look after him, grumbles about babysitting and stays in Blood Watch, where, Clopper complains, he mostly drinks.', 'npc_text 9054; quest 9548 description and reward; quest 9549 description and reward; quest 10063 description and reward'),
(352529, 3, 3525, 1, 1, 0, 'Trials of the Hand', 'Young draenei who hope to join the Hand of Argus are sent north to Kessel''s Crossing, mocked on their way by a pack handler sure they will never make it. At the crossing Vorkhan the herder puts them to work culling the ravagers that the Exodar carried as specimens and lost into the wild. Then Kessel takes their measure. Blood elf activity near his camp had doubled in a week, and agents reported that the Sunhawks meant to strike Azuremyst, so he lent his own elekk for a race against time: warn High Chief Stillpine, Exarch Menelaous and Admiral Odesyus, and be back in all haste. Next he sent the recruit to Wrathscale Lair, where naga had dared creep up on the camp by night, to slay Lord Xiz and drive a draenei banner through his body. Those who passed were sent up the road to Blood Watch, where Exarch Admetius asked what Argus meant to them and handed them over to the Triumvirate for the real training.', 'quest 9625 description and reward; quest 9634 description; quest 9663 description and reward (15 minutes); quest 9666 description; quest 9668 description; quest 9693 description'),
(352530, 3, 3525, 2, 1, 0, 'The Sun Gate', 'Under Vindicator Boros, the Hand''s recruits learned that the blood elves they had fought aboard the Exodar had survived the crash, and that their numbers never seemed to shrink. A missive taken from a Sunhawk was written in Thalassian, and Interrogator Elysia translated it: a declaration from Kael''thas Sunstrider himself, promising his Sunhawks reinforcements from Tempest Keep through a sun portal, the recapture of the Exodar and Velen''s punishment. Elysia also warned of a spy among the draenei, and trusting no messenger, she sent the news straight to the Prophet. Velen reasoned that such rifts must leave traces, and at the Warp Piston void anomalies showed the portal had been opened many times. Meanwhile the Cryo-Core yielded no survivors, only blood elves, and the island''s red waters were traced to the leaking Vector Coil. The Sunhawks kept their gate on the move, but scouts found it south of the Coil, and Vindicator Aesom had its portal controllers cut down and the gate destroyed, severing their supply line.', 'quests 9694, 9779, 9696, 9698, 9699, 9700, 9703, 9748, 9746, 9740, 9741 descriptions and rewards; page_text 2943 (Declaration from the Sun King)'),
(352531, 3, 3525, 3, 1, 0, 'Ending Their World', 'With the gate gone, the Hand learned that the Sunhawks answered to Sironas, they meant to enslave O''ros and take back the Exodar, and they were using the fallout of the Vector Coil to poison the land. Exarch Admetius resolved to blow the Coil apart, but no one could get close enough to judge its defenses. So he cast a spell to make one of his agents seem a blood elf, and in that guise the agent drew the boastful Sunhawk prisoner out. Sironas, he let slip, was an eredar who had passed for draenei; he bragged that an abomination made from a captured vindicator of the Triumvirate guarded the Coil; and he gave away its two weak points, at its western and eastern bases. From Vindicator''s Rest, Vindicator Corin thinned the Sunhawk lines while Demolitionist Legoso waited for a volunteer. The volunteer and Legoso fought up the mountain together and blew the supports, and Sironas, torn from her siphoning, was slain. Blood Watch hailed its champion, and Velen bestowed the tabard of the Hand''s most revered.', 'quests 9753, 9756, 9759, 9760, 9761, 9762 descriptions and rewards; npc_text 9137-9141 (captured agent dialogue); creature_text 17982 (Legoso''s escort), 17658'),
(352532, 3, 3525, 4, 1, 0, 'The Fate of Saruan', 'Many families were aboard the Exodar, and few have found one another again. Morae of Blood Watch asked for any trace of her husband Galaen, a technician of the Cryo-Core, which now lies overrun by blood elves west of the outpost. Among the wreckage lay the body of a technician, its clothing torn open by looters, and his spirit lingered long enough to speak: he had survived the crash, only to be killed by the infiltrators, and his last thought was of her. His jeweled amulet was won back from the Sunhawks and brought to Morae, who confessed she had known in her heart. Nearby lay Galaen''s journal. Its final pages told of Vindicator Saruan of the Triumvirate, beaten senseless by a cruel lieutenant named Matis, who feared what Sironas would do if her prisoner died. The writing ended in a long line trailing off the page. Vindicator Kuros, Saruan''s pupil and successor, wept as he read, and his grief turned to anger at the name of Matis.', 'quest 9578 description; quest 9579 description and reward; creature_text 17426 (Galaen''s spirit); page_text 2937; quest 9706 description and reward'),
(352533, 3, 3525, 5, 1, 0, 'The Bloodcurse', 'Admiral Odesyus had a strange visitor one night: the ghost of Edward Hanes, captain of the Lost Hope, dead these twenty years. Shaken, the admiral sent word asking someone to find the captain on Wyrmscar Island. Hanes had a grim tale. When the world was sundered, he said, this land cried loudest of all; thousands of night elves were lost, and in their place rose the naga, loyal to their twisted queen Azshara and bent on destroying all who sailed their sea. The bloodcurse spoiled the waters of the reef and sank ship after ship, and those it claimed could not rest. First the bloodcursed naga were driven from the reef. Then the hopeless ones, ghosts of voyagers taken by the curse, were destroyed so that their souls could find peace. Last, the statue of Azshara on Bloodcurse Isle was burned in effigy, drawing out Atoph the Bloodcursed, leader of the naga, to his death. Hundreds of souls, Hanes said, were grateful.', 'quests 9751, 9672, 9674, 9682, 9683 descriptions and rewards; creature_text 17715'),
(352534, 3, 3525, 6, 1, 0, 'The Dragon Riders of Loreth''Aran', 'For ten thousand years the ghost of Prince Toreth has kept watch on Wyrmscar Island. In his lifetime Ysera, Aspect of the Dream, gifted his kingdom with her brood, and his people rode green dragons into battle for centuries, until Ysera''s favor roused the ire of Deathwing and the black dragonflight fell on them as they slept. The greens rose to protect their riders, and none were spared. Now the once tranquil owlkin of Ragefeather Ridge have been coming to the island to steal the dragons'' bones for some ritual, and the spirits of the brood have grown restless. The bones were recovered, and the whelps and broodlings, bound to the land as Toreth is, were released toward the Dream. Then the bones were laid on the ever-burning pyre atop the island''s peak, calling down the spectral Razormaw, a lieutenant of Deathwing whose hatred outlasted death. With the black dragon destroyed, Toreth gave a token of Loreth''Aran in honor of the deed.', 'quests 9687, 9688, 9689 descriptions and rewards; npc_text 9058, 9059'),
(352535, 3, 3525, 7, 1, 0, 'Nolkai''s Words', 'Among the things Clopper Wizbang passed along was a treasure map a sailor had given him to cover a gambling debt. Drawn with an unsteady hand, it showed a pavilion of broken columns west of a half sunken tower on the eastern coast. There, in the ruins of Loreth''Aran, lay an old journal in an elegant script, its pages buried under the mapmaker''s tales of drunken shore leave. Anchorite Paetheus of Blood Watch, whose collection holds tools and knowledge from many cultures, separated the two. The last entry of the journal''s first author, Nolkai, told of a desperate end: the enemy nearly upon them, the survivors gathered in a temple to the east for a final stand, and Nolkai''s last possessions buried on its grounds in the hope that someone would one day learn what had happened there. The mound was still there. Inside lay a box holding a lantern, a bag that looked almost new, and a band engraved by a lover praying that Elune watch over Nolkai.', 'quests 9549 reward, 9550, 9557, 9561 descriptions and rewards; item_template 23847 (band inscription), 23852 (bag), item_loot_template 23846; npc_text 9029');
